# Every input and output of this project, on the box's own channels so it
# runs with nothing wired. To use a remote I/O module, declare it and change
# the device on each line, for example:
#   device rio modbus-tcp 192.168.1.50:502 unit=1 timeout_ms=300 poll_ms=20
#   in  start_pb bool rio di:0
# The plant model presses start by itself, so if this box's own channels are
# wired to anything, these lines drive it: check them before you deploy.
in  start_pb        bool box di:0
in  stop_pb         bool box di:1
in  ack_pb          bool box di:2
in  damper_open_in  bool box di:3
in  damper_shut_in  bool box di:4
in  fan_fb_in       bool box di:5
in  fan_overload_in bool box di:6
in  airflow_in      bool box di:7
in  freeze_in       bool box di:8
in  sim_belt_broken bool box di:9
out damper     bool box do:0 safe=false
out fan        bool box do:1 safe=false
out lamp_green bool box do:2 safe=false
out lamp_red   bool box do:3 safe=false
out state int screen state safe=0
# With a real analog output, point valve_pct at it. On a freeze trip the
# output goes to 100; decide its safe value with your coil in mind.
out valve_pct real screen valve_pct unit=pct
out supply_c  real screen supply_c unit=degC
out filter_pa real screen filter_pa unit=Pa
